// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./CasinoGameBaseV7.sol";

/**
 * @title ElRushEngineV7 — cluster pays + multiplier spots (math v1)
 * @notice BIT-FOR-BIT mirror of playRoundSeed(seed, mode, cap, MATH_V1) in the app's rushEngine.ts.
 *
 * Board 7×7, index = col*7 + row (row 0 = top). 5+ of a symbol touching up/down/left/right pay.
 * Every cell of a winning cluster explodes and marks its spot; a marked spot that explodes again is
 * ×2, then doubles per explosion up to ×128. A cluster pays pay(symbol, size) × (Σ multipliers under
 * it, or ×1 if none). Survivors fall, fresh cells fill from the top, until nothing pays (≤ 60 tumbles).
 * Base game: spots reset after the spin. 3+ scatters → free spins (3:10 4:12 5:15 6:20 7+:30) whose
 * spots persist for the whole feature; 3+ scatters in a free spin add the same again (≤ 60 spins).
 *
 * Gas layout: the grid is ONE word (4 bits per cell: 0-6 symbols, 7 scatter), the spots another
 * (4 bits per cell: 0 none, 1 marked, k ≥ 2 → ×2^(k-1)). Clusters are found with 49-bit masks:
 * flood fill = repeated dilation (shift ±1 inside a column, ±7 across columns) intersected with the
 * symbol's mask. The RNG hashes in scratch space.
 *
 * RNG stream: draw i = 64-bit chunk (i % 4) of keccak256(seed ‖ uint32(i / 4)), lowest first.
 * Draw order: (buy) 4th-scatter roll → 49 cells in index order → (buy) forced scatter positions →
 * per tumble, per column left→right, fresh cells top→bottom.
 */
library ElRushEngineV7 {
    uint256 internal constant BP = 10000;
    uint256 internal constant MAX_WIN_X = 5000;
    uint256 internal constant MAX_FREE = 60;
    uint256 internal constant MAX_TUMBLES = 60;
    uint256 internal constant SCATTER = 7;
    uint256 internal constant PAY_SCALE = 24854;
    uint8 internal constant MODE_BASE = 0;
    uint8 internal constant MODE_ANTE = 1;
    uint8 internal constant MODE_BUY = 2;

    uint256 internal constant FULL = (uint256(1) << 49) - 1;
    struct Rng { bytes32 seed; uint256 i; uint256 word; }

    function _mod(Rng memory r, uint256 n) private pure returns (uint256) {
        uint256 i = r.i;
        uint256 k = i & 3;
        uint256 w;
        if (k == 0) {
            bytes32 s = r.seed;
            assembly ("memory-safe") {
                mstore(0x00, s)
                mstore(0x20, shl(224, shr(2, i)))
                w := keccak256(0x00, 0x24)
            }
            r.word = w;
        } else {
            w = r.word;
        }
        unchecked { r.i = i + 1; }
        return ((w >> (64 * k)) & 0xFFFFFFFFFFFFFFFF) % n;
    }

    /// @dev one fresh cell (0-6 symbol, 7 scatter). free = the free-spins reel set.
    function _draw(Rng memory r, bool free_, uint256 sw) private pure returns (uint256) {
        if (!free_) {
            uint256 x = _mod(r, 12900 + sw);
            if (x < 2600) return 0;
            if (x < 5000) return 1;
            if (x < 7200) return 2;
            if (x < 9100) return 3;
            if (x < 10700) return 4;
            if (x < 11900) return 5;
            if (x < 12900) return 6;
            return SCATTER;
        } else {
            uint256 x = _mod(r, 13295 + sw);
            if (x < 3450) return 0;
            if (x < 6370) return 1;
            if (x < 8745) return 2;
            if (x < 10570) return 3;
            if (x < 11845) return 4;
            if (x < 12720) return 5;
            if (x < 13295) return 6;
            return SCATTER;
        }
    }

    function _value(uint256 s) private pure returns (uint256) {
        if (s == 0) return 20; if (s == 1) return 25; if (s == 2) return 30; if (s == 3) return 40;
        if (s == 4) return 50; if (s == 5) return 75; return 100;
    }
    function _curve(uint256 t) private pure returns (uint256) {
        if (t == 0) return 10; if (t == 1) return 15; if (t == 2) return 20; if (t == 3) return 25;
        if (t == 4) return 35; if (t == 5) return 50; if (t == 6) return 75; if (t == 7) return 100;
        if (t == 8) return 150; if (t == 9) return 250; return 500;
    }
    /// @dev pay in bp of bet for a cluster of `size` (≥ 5) of symbol `s`
    function _pay(uint256 s, uint256 size) private pure returns (uint256) {
        uint256 t = size - 5; if (t > 10) t = 10;
        return (_value(s) * _curve(t) * PAY_SCALE) / 1000;
    }

    function _award(uint256 sc) private pure returns (uint256) {
        return sc >= 7 ? 30 : sc == 6 ? 20 : sc == 5 ? 15 : sc == 4 ? 12 : sc == 3 ? 10 : 0;
    }

    function _popcount(uint256 x) private pure returns (uint256 c) {
        unchecked {
            x = x - ((x >> 1) & 0x5555555555555555);
            x = (x & 0x3333333333333333) + ((x >> 2) & 0x3333333333333333);
            x = (x + (x >> 4)) & 0x0F0F0F0F0F0F0F0F;
            c = (x * 0x0101010101010101 & 0xFFFFFFFFFFFFFFFF) >> 56;
        }
    }

    /// @dev rows 0 and 6 as 49-bit masks
    function _rowMasks() private pure returns (uint256 r0, uint256 r6) {
        unchecked { for (uint256 c = 0; c < 7; ++c) { r0 |= uint256(1) << (c * 7); r6 |= uint256(1) << (c * 7 + 6); } }
    }

    /// @dev one spin; `spots` is read and updated in place (memory word holder)
    function _spin(Rng memory r, bool free_, uint256 sw, uint256[1] memory spots, uint256 force)
        private pure returns (uint256 winBP, uint256 scatters)
    {
        unchecked {
            uint256 g;
            for (uint256 i = 0; i < 49; ++i) g |= _draw(r, free_, sw) << (i * 4);
            uint256 placed;
            while (placed < force) {
                uint256 k = _mod(r, 49);
                if ((g >> (k * 4)) & 0xF == SCATTER) continue;
                g = (g & ~(uint256(0xF) << (k * 4))) | (SCATTER << (k * 4));
                placed++;
            }
            (uint256 row0, uint256 row6) = _rowMasks();
            uint256 notR0 = FULL & ~row0;
            uint256 notR6 = FULL & ~row6;
            uint256 sp = spots[0];
            for (uint256 t = 0; t < MAX_TUMBLES; ++t) {
                // per-symbol masks
                uint256[7] memory m;
                for (uint256 i = 0; i < 49; ++i) {
                    uint256 s = (g >> (i * 4)) & 0xF;
                    if (s < 7) m[s] |= uint256(1) << i;
                }
                uint256 boom; uint256 stepBP;
                for (uint256 s = 0; s < 7; ++s) {
                    uint256 left = m[s];
                    while (left != 0) {
                        uint256 comp = left & (~left + 1);           // lowest set bit
                        while (true) {
                            uint256 n = (comp | ((comp << 1) & notR0) | ((comp >> 1) & notR6) | (comp << 7) | (comp >> 7)) & left;
                            if (n == comp) break;
                            comp = n;
                        }
                        left &= ~comp;
                        uint256 size = _popcount(comp);
                        if (size < 5) continue;
                        uint256 mult;
                        uint256 bits = comp;
                        while (bits != 0) {
                            uint256 low = bits & (~bits + 1);
                            uint256 k = _log2(low);
                            uint256 st = (sp >> (k * 4)) & 0xF;
                            if (st >= 2) mult += uint256(1) << (st - 1);
                            bits ^= low;
                        }
                        stepBP += _pay(s, size) * (mult > 0 ? mult : 1);
                        boom |= comp;
                    }
                }
                if (boom == 0) break;
                winBP += stepBP;
                // mark / grow the spots under every exploded cell (cap 8 = ×128)
                uint256 b = boom;
                while (b != 0) {
                    uint256 low = b & (~b + 1);
                    uint256 k = _log2(low);
                    uint256 st = (sp >> (k * 4)) & 0xF;
                    if (st < 8) sp += uint256(1) << (k * 4);
                    b ^= low;
                }
                // gravity: survivors keep order and sink; fresh cells fill each column from the top
                uint256 ng;
                for (uint256 c = 0; c < 7; ++c) {
                    uint256 keep; uint256 n;
                    for (uint256 row = 0; row < 7; ++row) {
                        uint256 idx = c * 7 + row;
                        if ((boom >> idx) & 1 == 0) { keep |= ((g >> (idx * 4)) & 0xF) << (n * 4); n++; }
                    }
                    uint256 fresh = 7 - n;
                    for (uint256 row = 0; row < fresh; ++row) ng |= _draw(r, free_, sw) << ((c * 7 + row) * 4);
                    for (uint256 j = 0; j < n; ++j) ng |= ((keep >> (j * 4)) & 0xF) << ((c * 7 + fresh + j) * 4);
                }
                g = ng;
            }
            spots[0] = sp;
            for (uint256 i = 0; i < 49; ++i) if ((g >> (i * 4)) & 0xF == SCATTER) scatters++;
        }
    }

    /// @dev index of the single set bit of a power of two (< 2^49)
    function _log2(uint256 x) private pure returns (uint256 n) {
        unchecked {
            if (x >= 1 << 32) { x >>= 32; n += 32; }
            if (x >= 1 << 16) { x >>= 16; n += 16; }
            if (x >= 1 << 8) { x >>= 8; n += 8; }
            if (x >= 1 << 4) { x >>= 4; n += 4; }
            if (x >= 1 << 2) { x >>= 2; n += 2; }
            if (x >= 1 << 1) { n += 1; }
        }
    }

    /// @return totalBP round win in bp of bet, capped at maxWinX × 1e4
    /// @return freeSpins free spins played
    function play(bytes32 seed, uint8 mode, uint256 maxWinX) internal pure returns (uint256 totalBP, uint256 freeSpins) {
        uint256 cap = (maxWinX < MAX_WIN_X ? maxWinX : MAX_WIN_X) * BP;
        Rng memory r = Rng(seed, 0, 0);
        uint256 force = mode == MODE_BUY ? 3 + (_mod(r, 100) < 6 ? 1 : 0) : 0;
        uint256[1] memory spots;
        (uint256 total, uint256 sc) = _spin(r, false, mode == MODE_ANTE ? 107 : 92, spots, force);
        uint256 left = _award(sc);
        if (left > 0 && total < cap) {
            spots[0] = 0;
            while (left > 0 && freeSpins < MAX_FREE && total < cap) {
                left--;
                (uint256 w, uint256 s2) = _spin(r, true, 60, spots, 0);
                total += w;
                left += _award(s2);
                freeSpins++;
            }
        }
        totalBP = total < cap ? total : cap;
    }
}

/**
 * @title ElRushGameV7 — ELRUSH on the V7 base (same room model as ELGATES V7).
 *
 * House protections:
 *  - RTP cap 99% (rtpCap). Raw engine EV ≈ 0.98 at the 5000× cap and the pool keeps 98% of every
 *    stake (1% platform + 1% creator), so even at the cap players get ~97% and stakers keep ~+1%.
 *  - Limit caps: maxWin ≤ 25% / maxBet ≤ 5% of available liquidity regardless of config.
 *  - Worst case (bet × maxWinX × rtp) is reserved at commit; payout ≤ reserve by construction.
 *  - Outcome from a FUTURE L2 block hash; reveal is permissionless and pays the round's player;
 *    rounds past the hash window are closed automatically (stake stays with the house).
 */
contract ElRushGameV7 is CasinoGameBaseV7 {
    uint256 public constant RTP_CAP_BP = 9900;
    uint256 public constant MAX_WIN_BP_CAP = 2500;
    uint256 public constant MAX_BET_RATIO_CAP = 500;
    uint256 public constant BUY_PRICE_MIN = 100;
    uint256 public constant BUY_PRICE_MAX = 250;
    uint256 public constant ANTE_PCT = 125;

    uint256 public immutable maxWinX;
    bool public immutable anteEnabled;
    bool public immutable buyEnabled;
    uint256 public immutable buyPriceX;

    struct Round {
        address player; uint48 commitBlock; uint16 rtpBP; uint8 mode; bool settled; uint16 freeSpins;
        uint112 bet; uint112 stake; uint32 rawBP;
        uint128 maxPayout; uint128 payout;
    }
    mapping(uint256 => Round) internal _rounds;
    uint256 public totalRounds;

    event RoundCommitted(uint256 indexed id, address indexed player, uint8 mode, uint256 bet, uint256 stake);
    event RoundSettled(uint256 indexed id, address indexed player, bytes32 seed, uint8 mode, uint256 rawBP, uint256 payout, uint16 freeSpins);
    event RoundForfeited(uint256 indexed id, address indexed player);

    struct Params { uint256 maxWinX; bool anteEnabled; bool buyEnabled; uint256 buyPriceX; }

    constructor(InitArgs memory a, Params memory p) CasinoGameBaseV7(a) {
        if (a.maxWinBP > MAX_WIN_BP_CAP || a.maxBetRatio > MAX_BET_RATIO_CAP) revert BadConfig();
        if (!(p.maxWinX == 500 || p.maxWinX == 1000 || p.maxWinX == 2500 || p.maxWinX == 5000)) revert BadConfig();
        if (p.buyEnabled && (p.buyPriceX < BUY_PRICE_MIN || p.buyPriceX > BUY_PRICE_MAX)) revert BadConfig();
        maxWinX = p.maxWinX; anteEnabled = p.anteEnabled; buyEnabled = p.buyEnabled; buyPriceX = p.buyPriceX;
    }

    /// @notice typical gas of one reveal (sets the ETH reveal fee a commit carries — see CasinoGameBaseV7.revealFeeQuote)
    function revealGas() public pure override returns (uint256) { return 2_000_000; }
    function _betCount() internal view override returns (uint256) { return totalRounds; }
    function rtpCap() public pure override returns (uint256) { return RTP_CAP_BP; }
    function effectiveRtp() public view returns (uint256) { return config.rtpBP; }
    function mathVersion() external pure returns (uint256) { return 1; }

    function stakeFor(uint256 bet, uint8 mode) public view returns (uint256) {
        if (mode == ElRushEngineV7.MODE_ANTE) return (bet * ANTE_PCT) / 100;
        if (mode == ElRushEngineV7.MODE_BUY) return bet * buyPriceX;
        return bet;
    }

    function _caps() private view returns (uint256 ratio, uint256 mwBP) {
        Config memory c = config;
        ratio = c.maxBetPoolRatio < MAX_BET_RATIO_CAP ? c.maxBetPoolRatio : MAX_BET_RATIO_CAP;
        mwBP = c.maxWinBP < MAX_WIN_BP_CAP ? c.maxWinBP : MAX_WIN_BP_CAP;
    }

    /// @notice Largest bet (not stake) accepted right now for `mode` — mirrors every check in commit.
    function maxBet(uint8 mode) external view returns (uint256) {
        uint256 avail = availableLiquidity();
        uint256 costBP = mode == ElRushEngineV7.MODE_ANTE ? ANTE_PCT * 100 : mode == ElRushEngineV7.MODE_BUY ? buyPriceX * BP : BP;
        uint256 payBP = maxWinX * config.rtpBP;
        (uint256 ratio, uint256 mwBP) = _caps();
        uint256 byRatio = (avail * ratio) / costBP;
        uint256 byWin = payBP > costBP ? (avail * mwBP) / (payBP - costBP) : type(uint256).max;
        uint256 bySolv = (avail * BP) / payBP;
        uint256 m = byRatio < byWin ? byRatio : byWin;
        return m < bySolv ? m : bySolv;
    }

    function commit(uint256 bet, uint8 mode) external payable nonReentrant withRevealFee whenNotPaused returns (uint256 id) {
        if (mode > ElRushEngineV7.MODE_BUY) revert BadInput();
        if (mode == ElRushEngineV7.MODE_ANTE && !anteEnabled) revert BadInput();
        if (mode == ElRushEngineV7.MODE_BUY && !buyEnabled) revert BadInput();
        if (bet == 0 || bet < config.minBet) revert BelowMinBet();
        uint256 nowB = _beginBet();
        uint256 stake = stakeFor(bet, mode);
        uint16 rtp = config.rtpBP;
        uint256 maxPayout = (bet * maxWinX * rtp) / BP;
        uint256 avail = availableLiquidity();
        (uint256 ratio, uint256 mwBP) = _caps();
        if (stake > (avail * ratio) / BP) revert BetExceedsMax();
        if (maxPayout > (avail * mwBP) / BP + stake) revert WinExceedsMax();
        _openBet(stake, maxPayout);
        _pullAndFee(stake);
        id = totalRounds++;
        _rounds[id] = Round(msg.sender, uint48(nowB), rtp, mode, false, 0, uint112(bet), uint112(stake), 0, uint128(maxPayout), 0);
        _recordBet(msg.sender, id);
        emit RoundCommitted(id, msg.sender, mode, bet, stake);
    }

    /// @notice Permissionless: anyone may settle; the payout always goes to the round's player.
    function reveal(uint256 id) external nonReentrant paysReveal(id) returns (uint256 payout) {
        Round storage r = _rounds[id];
        if (r.player == address(0)) revert NotFound();
        if (r.settled) revert AlreadySettled();
        bytes32 seed = _seed(r.commitBlock, r.player, id);
        (uint256 rawBP, uint256 fs) = ElRushEngineV7.play(seed, r.mode, maxWinX);
        payout = (uint256(r.bet) * rawBP * r.rtpBP) / (BP * BP);
        r.settled = true; r.rawBP = uint32(rawBP); r.payout = uint128(payout); r.freeSpins = uint16(fs);
        _closeBet(r.player, r.maxPayout, payout);
        emit RoundSettled(id, r.player, seed, r.mode, rawBP, payout, uint16(fs));
    }

    function forfeit(uint256 id) external nonReentrant {
        Round storage r = _rounds[id];
        if (r.player == address(0)) revert NotFound();
        if (r.settled) revert AlreadySettled();
        if (!_expireBet(id, _l2())) revert TooEarly();
    }

    function _expireBet(uint256 id, uint256 nowB) internal override returns (bool) {
        Round storage r = _rounds[id];
        if (r.settled) return true;
        if (!_isExpired(r.commitBlock, nowB)) return false;
        r.settled = true;
        _closeBet(r.player, r.maxPayout, 0);
        _countExpired();
        emit RoundForfeited(id, r.player);
        return true;
    }

    /// @notice Replay any seed (the UI and auditors use this to verify a settled round).
    function previewRound(bytes32 seed, uint8 mode) external view returns (uint256 rawBP, uint256 freeSpins) {
        return ElRushEngineV7.play(seed, mode, maxWinX);
    }

    /// @notice ELGATES-shaped view. `seed` is in the RoundSettled event (not stored).
    function rounds(uint256 id) external view returns (
        address player, uint8 mode, bool settled, uint16 freeSpins,
        uint256 bet, uint256 stake, uint256 maxPayout, uint256 rtpBP, uint256 commitBlock,
        uint256 rawBP, uint256 payout, bytes32 seed
    ) {
        Round storage r = _rounds[id];
        return (r.player, r.mode, r.settled, r.freeSpins, r.bet, r.stake, r.maxPayout, r.rtpBP, r.commitBlock, r.rawBP, r.payout, bytes32(0));
    }
    function userRounds(address u, uint256 i) external view returns (uint256) { return _userBetAt(u, i); }
    function getUserRoundCount(address u) external view returns (uint256) { return _userBetCount(u); }
}
